package com.dy.artisan3d.ui.componentimport android.text.Htmlimport android.widget.TextViewimport androidx.compose.material3.MaterialThemeimport androidx.compose.runtime.Composableimport androidx.compose.ui.Modifierimport androidx.compose.ui.graphics.Colorimport androidx.compose.ui.graphics.toArgbimport androidx.compose.ui.platform.LocalContextimport androidx.compose.ui.viewinterop.AndroidView@Composableactual fun ArtisanHtmlText(    html: String,    modifier: Modifier,    selectable: Boolean,    color: Color) {    val context = LocalContext.current    val bodyLargeSize = MaterialTheme.typography.bodyLarge.fontSize.value // Odatda 16f    AndroidView(        modifier = modifier,        factory = { ctx ->            TextView(ctx).apply {                setTextIsSelectable(selectable)                // Matnni ikki chetga tekislash (Justify)                if (android.os.Build.VERSION.SDK_INT >= android.os.Build.VERSION_CODES.O) {                    justificationMode = android.graphics.text.LineBreaker.JUSTIFICATION_MODE_INTER_WORD                }                textSize = bodyLargeSize            }        },        update = { textView ->            textView.text = Html.fromHtml(html, Html.FROM_HTML_MODE_COMPACT)            textView.setTextColor(color.toArgb())        }    )}